<template><div class="space-y-3 p-4"><h1 class="text-xl font-bold text-slate-800">Orders</h1><NuxtLink v-for="item in items" :key="item.id" :to="`/buyer/orders/${item.id}`" class="m-card block"><div class="flex justify-between gap-3"><p class="text-sm font-semibold text-slate-800">Order {{ item.id.slice(0, 8) }}</p><span class="status-pill bg-indigo-50 text-indigo-600">{{ item.status }}</span></div><p class="mt-3 text-lg font-bold text-slate-800">{{ money(item.total_minor, item.currency) }}</p></NuxtLink><p v-if="error" class="m-card text-sm text-red-600">{{ error }}</p></div></template>
<script setup lang="ts">definePageMeta({ middleware: ['auth'] }); const { listOrders } = useCommerce(); const items = ref<any[]>([]); const error = ref(''); const money = (value: number, currency: string) => new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(value / 100); onMounted(async () => { try { items.value = (await listOrders()).items } catch (e: any) { error.value = e?.data?.detail || e?.message } })</script>
